import{_ as a,o as t,c as n,a0 as p}from"./chunks/framework.BmibOe8h.js";const g=JSON.parse('{"title":"凌晨两点","description":"一些睡不着的时候想的事。","frontmatter":{"title":"凌晨两点","date":"2026-08-03T00:00:00.000Z","description":"一些睡不着的时候想的事。"},"headers":[],"relativePath":"blog/2026-08-03-ling-chen-liang-dian.md","filePath":"blog/2026-08-03-ling-chen-liang-dian.md","lastUpdated":1785699015000}'),o={name:"blog/2026-08-03-ling-chen-liang-dian.md"};function i(c,e,d,s,l,r){return t(),n("div",null,[...e[0]||(e[0]=[p("<p>凌晨两点，手机屏幕是房间里唯一的光源。刷完最后一条动态，锁屏，世界变回全黑。</p><p>这种时候脑子不太受控。白天被各种事情压住的念头会自己浮上来——内核编译报错怎么修、明天要不要 rebase 那个分支、上次那个 patch 为什么会在 6.1.128 上炸掉。但这些东西想一会儿就腻了，真正绕不过去的永远是那几个问题。</p><p>比如她今天跟谁吃了饭，为什么不回消息。比如那个男同事为什么总在她的朋友圈下面秒赞。比如她刚才那个微信弹出来的时候下意识把屏幕往自己那边侧了一下。</p><p>我知道这些念头很蠢。但凌晨两点没有理性。</p><p>在 CI 里 debug 的时候我能盯着日志看一个小时不眨眼，因为每一行输出都有因有果。<code>make</code> 失败就是缺依赖，<code>patch</code> 报错就是上下文不匹配，SELinux denial 就是策略没写对——每件事都有确定的根因。查到了，改掉，重跑，绿灯。</p><p>但人不是这样的。人的行为没有日志可查，没有 <code>dmesg</code> 能告诉你刚才那句话背后的情绪是什么，没有 <code>git blame</code> 能帮你找到一段关系里是谁先开始冷淡的。</p><p>有时候我觉得内核比人简单太多了。内核不会骗你，它就是这么写的，能跑就是能跑，炸了就是炸了。commit message 写清楚了改动意图，你信就行。但人说的话里有多少是真的，多少是出于礼貌，多少是为了省掉解释的麻烦——你不知道。</p><p>可能是想多了。也可能是没想够。</p><p>三点钟强迫自己放下手机。明天还要推一个版本，CI 队列还在排。内核不会因为我的胡思乱想就自己编译好，该修的 bug 一个都不会少。有些事情没有 root cause，就算有，也不是我能修的。</p><p>睡了。</p>",10)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
